css:
*{
margin:0;
padding:0;
box-sizing:border-box;
font-family:"Inter","Helvetica",sans-serif;
}





body{
background:linear-gradient(135deg,#667eea,#764ba2);
min-height:100vh;
padding-top:80px;
}




.navbar{

position:fixed;
top:0;
left:0;

width:100%;
height:70px;

background:white;

display:flex;
align-items:center;
justify-content:space-between;

padding:0 40px;

box-shadow:0 4px 20px rgba(0,0,0,0.1);

z-index:100;

}



.logo{

font-size:22px;
font-weight:700;
color:#333;

}



.login-btn{

background:linear-gradient(135deg,#667eea,#764ba2);

color:white;

padding:10px 18px;

border-radius:8px;

text-decoration:none;

font-size:14px;

font-weight:600;

transition:0.2s;

}



.login-btn:hover{

transform:translateY(-1px);

box-shadow:0 6px 15px rgba(0,0,0,0.15);

}



.registration-wrapper{

max-width:900px;
width:100%;

margin:auto;

padding:40px;

background:white;

border-radius:14px;

box-shadow:0 20px 40px rgba(0,0,0,0.2);

}



/* TITLE */

.reg-title{

text-align:center;

font-size:32px;

font-weight:700;

margin-bottom:35px;

color:#222;

}



.section-title{

font-size:20px;

font-weight:600;

margin-top:30px;

margin-bottom:15px;

border-left:5px solid #667eea;

padding-left:10px;

color:#333;

}



/* GRID */

.grid{

display:grid;

grid-template-columns:1fr 1fr;

gap:20px;

}




.field{

display:flex;

flex-direction:column;

}



.field label{

font-size:14px;

font-weight:600;

margin-bottom:6px;

color:#444;

}





.field input,
.field select{

padding:11px;

border:1px solid #ddd;

border-radius:8px;

font-size:14px;

background:white;

transition:0.2s;

}



.field input:focus,
.field select:focus{

border-color:#667eea;

box-shadow:0 0 0 3px rgba(102,126,234,0.15);

outline:none;

}





.register-btn{

margin-top:30px;

width:100%;

padding:14px;

background:linear-gradient(135deg,#667eea,#764ba2);

color:white;

border:none;

border-radius:10px;

font-size:16px;

font-weight:600;

cursor:pointer;

transition:0.25s;

}



.register-btn:hover{

transform:translateY(-2px);

box-shadow:0 10px 20px rgba(0,0,0,0.15);

}





.add-app-btn{

background:linear-gradient(135deg,#2ecc71,#27ae60);

color:white;

border:none;

padding:11px 18px;

font-size:14px;

font-weight:600;

border-radius:8px;

cursor:pointer;

transition:0.2s;

}



.add-app-btn:hover{

transform:translateY(-1px);

box-shadow:0 6px 15px rgba(0,0,0,0.15);

}




.app-table{

width:100%;

border-collapse:collapse;

margin-top:15px;

border-radius:10px;

overflow:hidden;

}



.app-table thead{

background:#f4f6ff;

}



.app-table th{

padding:12px;

text-align:left;

font-size:14px;

color:#444;

}



.app-table td{

padding:12px;

font-size:14px;

border-top:1px solid #eee;

}



.app-table tr:hover{

background:#fafbff;

}





.app-table button{

background:#e74c3c;

border:none;

color:white;

padding:6px 12px;

border-radius:6px;

cursor:pointer;

font-size:13px;

transition:0.2s;

}



.app-table button:hover{

background:#c0392b;

}




@media (max-width:900px){

.registration-wrapper{
padding:30px;
}

.grid{
grid-template-columns:1fr;
}

}





@media (max-width:600px){

.reg-title{
font-size:26px;
}

.section-title{
font-size:18px;
}

.field input,
.field select{
font-size:13px;
padding:10px;
}

.register-btn{
font-size:15px;
padding:12px;
}

}



.app-select-row{

display:flex;

align-items:end;

gap:10px;

}




.app-select-row .field{

flex:1;

}




.app-select-row .add-app-btn{

height:42px;

white-space:nowrap;

}

javascript:
let selected_apps = []

window.onload = function(){
    loadOptions()
}


function loadOptions(){

    frappe.call({
        method:"quantbit_billing_platform.quantbit_billing_platform.doctype.billing_account_master.billing_account_master.get_registration_options",
        callback:function(r){

            let data = r.message

            let filtered_apps = data.apps.filter(app => 
                !["frappe", "erpnext"].includes(app)
            )

            setSelectOptions("default_currency", data.currencies)
            setSelectOptions("country", data.countries)
            setSelectOptions("app_select", filtered_apps)

        }
    })
}


function setSelectOptions(id, options, placeholderText = "Select Option"){

    let select = document.getElementById(id)

    select.innerHTML = ""

    let placeholder = document.createElement("option")
    placeholder.value = ""
    placeholder.innerText = placeholderText
    placeholder.disabled = true
    placeholder.selected = true

    select.appendChild(placeholder)

    options.forEach(o => {

        let opt = document.createElement("option")
        opt.value = o
        opt.innerText = o

        select.appendChild(opt)

    })
}


document.getElementById("add-app-btn").addEventListener("click", function(e){

    e.preventDefault()

    let app=document.getElementById("app_select").value

    if(!app){
        alert("Select App")
        return
    }

    // Prevent duplicate apps
    let exists = selected_apps.find(a => a.app_name === app)

    if(exists){
        alert("App already added")
        return
    }

    // Add to array
    selected_apps.push({
        app_name:app
    })

    renderAppTable()

})


function renderAppTable(){

    let tbody=document.querySelector("#app-table tbody")

    tbody.innerHTML=""

    selected_apps.forEach((a,index)=>{

        let row=document.createElement("tr")

        row.innerHTML=`
            <td>${a.app_name}</td>
            <td>
                <button type="button" onclick="removeApp(${index})">Delete</button>
            </td>
        `

        tbody.appendChild(row)

    })

}



function removeApp(i){

    selected_apps.splice(i,1)

    renderAppTable()

}



document.getElementById("billing-registration-form").addEventListener("submit",function(e){

    e.preventDefault()

    if(selected_apps.length === 0){
        alert("Please select at least one app")
        return
    }

    let data={

        company_name:document.getElementById("company_name").value,
        abbr:document.getElementById("abbr").value,
        default_currency:document.getElementById("default_currency").value,
        country:document.getElementById("country").value,

        email:document.getElementById("email").value,
        user_password:document.getElementById("user_password").value,
        first_name:document.getElementById("first_name").value,
        last_name:document.getElementById("last_name").value,

        billing_details:selected_apps
    }

    frappe.call({

        method:"quantbit_billing_platform.quantbit_billing_platform.doctype.billing_account_master.billing_account_master.create_billing_registration",

        args:{
            data: JSON.stringify(data)
        },

        callback:function(r){

            if(r.message.status==="success"){

                alert("Billing Account Created Successfully")

                window.location.href="/login"

            }

        }

    })

})
